import sys


def main():
    tok = sys.stdin.read().split()
    n, q = int(tok[0]), int(tok[1])
    par = [0, 0] + [int(tok[2 + i]) for i in range(n - 1)]
    children = [[] for _ in range(n + 1)]
    for v in range(2, n + 1):
        children[par[v]].append(v)
    depth = [0] * (n + 1)
    order = [1]
    for u in order:
        for c in children[u]:
            depth[c] = depth[u] + 1
            order.append(c)
    LOG = max(1, n.bit_length())
    up = [[1] * (n + 1)]
    up[0] = [1, 1] + par[2:]
    for k in range(1, LOG):
        prev = up[-1]
        up.append([prev[prev[v]] for v in range(n + 1)])
    pos = 2 + n - 1
    out = []
    for j in range(q):
        u, v = int(tok[pos + 2 * j]), int(tok[pos + 2 * j + 1])
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if diff >> k & 1:
                u = up[k][u]
        if u != v:
            for k in range(LOG - 1, -1, -1):
                if up[k][u] != up[k][v]:
                    u, v = up[k][u], up[k][v]
            u = up[0][u]
        out.append(str(u))
    print('\n'.join(out))


main()

