#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> par(n + 1, 1);
    vector<vector<int>> children(n + 1);
    for (int v = 2; v <= n; v++) {
        cin >> par[v];
        children[par[v]].push_back(v);
    }
    vector<int> depth(n + 1, 0), order{1};
    for (size_t i = 0; i < order.size(); i++) {
        int u = order[i];
        for (int c : children[u]) {
            depth[c] = depth[u] + 1;
            order.push_back(c);
        }
    }
    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    vector<vector<int>> up(LOG, vector<int>(n + 1, 1));
    for (int v = 2; v <= n; v++) up[0][v] = par[v];
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
    while (q--) {
        int u, v;
        cin >> u >> v;
        if (depth[u] < depth[v]) swap(u, v);
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++)
            if (diff >> k & 1) u = up[k][u];
        if (u != v) {
            for (int k = LOG - 1; k >= 0; k--)
                if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }
            u = up[0][u];
        }
        cout << u << '\n';
    }
    return 0;
}

